#include <stdio.h>
#include <elf.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>

int main() {
  int fd = open("example", O_RDONLY);
  if (fd == -1) return 1;
  Elf64_Ehdr header;
  read(fd, &header, sizeof(header));
  printf("ELF Magic: %x\n", header.e_ident[0] << 24 | header.e_ident[1] << 16 | header.e_ident[2] << 8 | header.e_ident[3]);
  close(fd);
  return 0;
}
